    def __init__(self):
        # Initialize all registers with their reset values
        self.regs = {
            0xD0: 0x58,  # id
            0xE0: 0x00,  # reset
            0xF3: 0x00,  # status
            0xF4: 0x00,  # ctrl_meas
            0xF5: 0x00,  # config
            0xF7: 0x80,  # press_msb
            0xF8: 0x00,  # press_lsb
            0xF9: 0x00,  # press_xlsb
            0xFA: 0x80,  # temp_msb
            0xFB: 0x00,  # temp_lsb
            0xFC: 0x00   # temp_xlsb
        }

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr in self.regs:
            return self.regs[addr]
        else:
            raise ValueError(f"Invalid address: {addr}")

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr in self.regs:
            if nbytes == 1:
                # Apply single-byte semantics for RO fields
                if addr in [0xD0, 0xE0, 0xF3]:
                    # Ignore writes to RO fields
                    return
                # Update only bits 15:8
                self.regs[addr] &= 0xFF
                self.regs[addr] |= (data & 0xFF) << 8
            else:
                # Update entire register
                self.regs[addr] = data
        else:
            raise ValueError(f"Invalid address: {addr}")

